{{-- One particulars row of an SOB Item form. $i is the row number (or __INDEX__ in the template for a row added by the button); $line is the saved row, if any. --}}
@php
    $cls = $box ?? 'mt-1.5 w-full rounded-lg border border-outline-variant bg-white px-3 py-2 text-sm font-normal normal-case tracking-normal text-on-surface shadow-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15';
    $val = fn (string $key, $fallback = '') => old("lines.$i.$key", $fallback);
    $num = fn ($value) => $value === null ? '' : rtrim(rtrim(number_format((float) $value, 2, '.', ''), '0'), '.');
@endphp
<div class="contents" data-row>
    @if($line)<input type="hidden" name="lines[{{ $i }}][id]" value="{{ $line->id }}">@endif
    <label class="text-[11px] font-bold uppercase tracking-wider text-on-surface-variant sob-f-cat">Category (where it belongs in the APP-CSE)<select name="lines[{{ $i }}][category]" data-category class="{{ $cls }}">@php $currentCategory = $val('category', $line ? $line->category : \App\Support\AppCategories::ALL[0]); $isPartOne = filled($currentCategory) && ! in_array($currentCategory, \App\Support\AppCategories::ALL, true); @endphp<option value="" @selected(blank($currentCategory)) title="Not goods (for example a travel budget): this line is not put in the APP">-</option><optgroup label="Part II · Not available at PS">@foreach(\App\Support\AppCategories::ALL as $category)<option value="{{ $category }}" @selected($category === $currentCategory || ($category === \App\Support\AppCategories::of($currentCategory) && filled($currentCategory) && ! $isPartOne))>{{ $category }}</option>@endforeach</optgroup><optgroup label="Part I · Available at PS">@foreach(\App\Support\AppCategories::partOne() as $category)<option value="{{ $category }}" data-part-one @selected($category === $currentCategory)>{{ $category }}</option>@endforeach</optgroup></select></label>
    <label class="text-[11px] font-bold uppercase tracking-wider text-on-surface-variant sob-f-part relative">Particulars<input name="lines[{{ $i }}][particulars]" required maxlength="255" autocomplete="off" data-catalog-search value="{{ $val('particulars', $line?->particulars) }}" class="{{ $cls }}" title="Type to find an item sold by the Procurement Service (it goes to Part I of the APP-CSE); anything else goes to Part II."><input type="hidden" name="lines[{{ $i }}][cse_catalog_item_id]" data-catalog-id value="{{ $val('cse_catalog_item_id', $line?->cse_catalog_item_id) }}"><span data-catalog-state class="absolute left-0 top-full mt-0.5 block whitespace-nowrap text-[10px] font-semibold normal-case tracking-normal {{ ($val('cse_catalog_item_id', $line?->cse_catalog_item_id) || $isPartOne) ? 'text-secondary' : 'text-on-surface-variant' }}">{{ ($val('cse_catalog_item_id', $line?->cse_catalog_item_id) || $isPartOne) ? 'APP-CSE Part I (Procurement Service item)' : 'APP-CSE Part II (not available at PS)' }}</span><div data-catalog-list class="absolute left-0 top-full z-30 hidden max-h-64 w-[24rem] max-w-[85vw] overflow-y-auto rounded-lg border border-outline-variant bg-white text-sm font-normal normal-case tracking-normal shadow-lg"></div></label>
    <label class="text-[11px] font-bold uppercase tracking-wider text-on-surface-variant sob-f-num">Frequency<input name="lines[{{ $i }}][frequency]" type="text" inputmode="decimal" value="{{ $val('frequency', $line ? $num($line->frequency) : 1) }}" class="{{ $cls }}"></label>
    <label class="text-[11px] font-bold uppercase tracking-wider text-on-surface-variant sob-f-num">Quantity<input name="lines[{{ $i }}][quantity]" type="text" inputmode="decimal" required value="{{ $val('quantity', $line ? $num($line->quantity) : '') }}" class="{{ $cls }}"></label>
    <label class="text-[11px] font-bold uppercase tracking-wider text-on-surface-variant sob-f-unit">Unit<input name="lines[{{ $i }}][unit]" required maxlength="50" value="{{ $val('unit', $line?->unit) }}" placeholder="pcs, ream, month" class="{{ $cls }}"></label>
    <label class="text-[11px] font-bold uppercase tracking-wider text-on-surface-variant sob-f-cost">Unit cost<input name="lines[{{ $i }}][unit_cost]" type="text" inputmode="decimal" required value="{{ $val('unit_cost', $line ? $num($line->unit_cost) : '') }}" class="{{ $cls }}"></label>
    <button type="button" data-remove-row class="justify-self-start rounded px-2 py-1 text-xs font-semibold text-error hover:bg-surface-low sob-f-remove">× Remove particulars</button>
</div>
